/// the top, then down the left beneath that; shaded along the bottom, then up
/// the right above that, so no two overlap. None for a surface too small.
pub fn bevel_edges(bounds: Bounds<Pixels>, palette: &Palette) -> Vec<(Bounds<Pixels>, Hsla)> {
    let (width, height) = (bounds.size.width, bounds.size.height);
    if width < BEVEL * 2. || height < BEVEL * 2. {
